script.setup:
// d3-scale-chromatic supplies the color maps; each is sampled into a 256-texel lookup texture that
// colors a drifting scalar field (warped noise plus a bump that follows the pointer).
const d3 = await ctx.utils.import("https://esm.sh/d3-scale-chromatic@3.1.0");
const MAPS = ["Viridis", "Magma", "Inferno", "Plasma", "Cividis", "Turbo", "Spectral", "RdBu", "PuOr", "Sinebow", "Rainbow", "YlGnBu"];
const gl = ctx.gl, lut = gl.createTexture();
gl.bindTexture(gl.TEXTURE_2D, lut);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
// Interpolators return "#rrggbb" or "rgb(r, g, b)" depending on the map.
const parse = (c) => c[0] === "#" ? [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16)) : c.match(/[\d.]+/g).slice(0, 3).map(Number);
const fs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_lut; uniform vec2 u_resolution; uniform vec4 u_mouse; uniform float u_time;
uniform float u_speed; uniform float u_scale; uniform float u_bands; uniform bool u_lines; uniform bool u_reverse;
vec2 h2(vec2 p) { p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3))); return fract(sin(p) * 43758.5453) * 2.0 - 1.0; }
float gnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);
  return mix(mix(dot(h2(i), f), dot(h2(i + vec2(1, 0)), f - vec2(1, 0)), u.x),
             mix(dot(h2(i + vec2(0, 1)), f - vec2(0, 1)), dot(h2(i + vec2(1, 1)), f - vec2(1, 1)), u.x), u.y);
}
float fbm(vec2 p) { float a = 0.0, m = 0.5; for (int i = 0; i < 4; i++) { a += m * gnoise(p); p = p * 1.97 + 3.1; m *= 0.42; } return a; }
float field(vec2 p) {
  float t = u_time * u_speed;
  vec2 q = vec2(fbm(p + vec2(0.0, t * 0.1)), fbm(p + vec2(5.2, 1.3) - t * 0.08));
  float v = fbm(p + 2.2 * q + vec2(t * 0.05, 0.0));
  return 0.5 + 2.6 * v;
}
void main() {
  float aspect = u_resolution.x / u_resolution.y;
  float bar = 0.06;
  if (v_uv.x > 1.0 - bar) {
    // color bar on the right
    float x = (v_uv.x - (1.0 - bar)) / bar;
    float t = (v_uv.y - 0.08) / 0.84;
    vec3 c = vec3(0.07);
    if (x > 0.3 && x < 0.75 && t >= 0.0 && t <= 1.0) {
      c = texture(u_lut, vec2(u_reverse ? 1.0 - t : t, 0.5)).rgb;
      if (u_lines && abs(fract(t * u_bands + 0.5) - 0.5) < 0.06) c = mix(c, vec3(0.0), 0.5);
    }
    outColor = vec4(c, 1.0); return;
  }
  vec2 p = vec2(v_uv.x * aspect, v_uv.y) * u_scale;
  vec2 m = vec2(u_mouse.x / u_resolution.y, u_mouse.y / u_resolution.y) * u_scale;
  float v = field(p) + 0.3 * exp(-dot(p - m, p - m) * 4.0 / (u_scale * u_scale));
  v = clamp(v, 0.0, 1.0);
  vec3 c = texture(u_lut, vec2(u_reverse ? 1.0 - v : v, 0.5)).rgb;
  if (u_lines) {
    // isolines: band edges, kept one pixel wide with fwidth
    float b = v * u_bands, w = fwidth(b);
    float line = 1.0 - smoothstep(0.0, w * 1.2, abs(fract(b + 0.5) - 0.5));
    c = mix(c, c * 0.35, line * 0.8);
  }
  outColor = vec4(c, 1.0);
}`;
Object.assign(ctx.state, { d3, MAPS, lut, parse, map: -1, p: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs) });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const map = Math.max(0, Math.min(s.MAPS.length - 1, u.u_map | 0));
if (map !== s.map) {
  s.map = map;
  const f = s.d3["interpolate" + s.MAPS[map]], px = new Uint8Array(256 * 4);
  for (let i = 0; i < 256; i++) { px.set(s.parse(f(i / 255)), i * 4); px[i * 4 + 3] = 255; }
  gl.bindTexture(gl.TEXTURE_2D, s.lut);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, 256, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, px);
  ctx.publish("color map", "interpolate" + s.MAPS[map]);
}
gl.useProgram(s.p);
ctx.utils.bindTexture(s.p, "u_lut", s.lut, 0);
ctx.utils.drawFullscreen(s.p);
